#pragma once

// The xenia-project/xenia PPC instruction tests' vector cases (register and
// memory values recorded on Xbox 360 hardware; see XENIA_PPC_TESTS_LICENSE),
// as data: xenia_ppc_vector_corpus.inc, generated by extract_corpus.py from
// the assembled tests/ppc/asm sources rexglue-sdk carries.
#include <cstdint>

struct XeniaPpcValue {
  // 'r' GPR, 'f' FPR, 'v' VR, 'c' the whole CR, '-' none (an empty list).
  char kind;
  unsigned index;
  std::uint64_t scalar;
  double real;
  std::uint32_t lanes[4];
};

struct XeniaPpcMemory {
  std::uint32_t address;
  unsigned size;  // bytes
  const std::uint8_t* bytes;
};

struct XeniaPpcCase {
  const char* name;
  const std::uint32_t* words;  // through the closing blr
  unsigned word_count;
  const XeniaPpcValue* in;
  unsigned in_count;
  const XeniaPpcValue* out;
  unsigned out_count;
  const XeniaPpcMemory* memory_in;
  unsigned memory_in_count;
  const XeniaPpcMemory* memory_out;
  unsigned memory_out_count;
};

// One table of cases: the xenia hardware corpus, or Xenon's own operand
// cases (xenon_vmx128_operands.inc) for encodings that corpus never reaches.
struct XeniaPpcCorpus {
  const XeniaPpcCase* cases;
  unsigned count;
};
